/* The site, the admin app and the seed must agree about what a page is made of.
 *
 * WHY THIS FILE EXISTS
 *
 * One rule lives in three places:
 *
 *   site/assets/blocks.js       which element each block belongs to
 *   admin/index.html            which fields the Pages screen offers
 *   db/supabase/migrations/     the seeded rows
 *
 * All three are generated by db/tools/extract-page-copy.py from one mapping, so
 * today they agree by construction. That is not the same as them agreeing in a
 * year. Somebody will hand edit one of them, or regenerate two and deploy one,
 * and this project's whole experience is that two copies of one rule drift.
 *
 * The failures are quiet in both directions. A field the admin app offers and
 * the site does not render is a screen that accepts somebody's work and throws
 * it away. A block the site reads and the admin app does not offer is a
 * paragraph that cannot be edited and nobody knows why.
 *
 * This is the ARCA Connect pattern: lift both definitions out of the files that
 * hold them and assert the sets match. It is the only defence that has ever
 * worked against one rule having two homes.
 *
 * Run:  node tests/12_page_keys.js  [path-to-site]  [path-to-admin]
 */
const fs = require('fs');
const path = require('path');

const ROOT  = path.resolve(__dirname, '..');
const SITE  = process.argv[2] || path.resolve(ROOT, '../site');
const ADMIN = process.argv[3] || path.resolve(ROOT, '../admin');
const MIG   = path.join(ROOT, 'supabase/migrations');

let pass = 0, fail = 0;
const ok = (c, what) => { if (c) pass++; else { fail++; console.log('  FAIL  ' + what); } };
const list = a => [...a].sort().join(', ');

// --- the site's idea -------------------------------------------------------
// Read as JSON rather than evaluated. A test that runs the file it is testing
// can be defeated by that file, and the generator writes it without trailing
// commas precisely so this is possible.
const blocksSrc = fs.readFileSync(path.join(SITE, 'assets/blocks.js'), 'utf8');
// Found by its own name: the icon drawings follow the map in the same file.
const bmAt = blocksSrc.indexOf('const BLOCK_MAP = ') + 'const BLOCK_MAP = '.length;
const BLOCK_MAP = JSON.parse(blocksSrc.slice(bmAt, blocksSrc.indexOf('\n};', bmAt) + 2));

// --- the admin app's idea --------------------------------------------------
// PAGES is inline in a 300KB single file page, so it is cut out by its own
// boundaries and parsed. The keys are unquoted, which JSON will not take, so
// the pairs are read with a regular expression over that slice only.
const adminSrc = fs.readFileSync(path.join(ADMIN, 'index.html'), 'utf8');
const pagesStart = adminSrc.indexOf('const PAGES =');
const pagesEnd   = adminSrc.indexOf('const SCREENS = [');
ok(pagesStart > -1, 'PAGES is in the admin app');
ok(pagesEnd > pagesStart, 'and it comes before SCREENS, which is where it is cut off');
const pagesSrc = adminSrc.slice(pagesStart, pagesEnd);

const PAGES = [];
const pageRe = /\{ key: "([^"]+)", title: "([^"]*)", path: "([^"]*)", fields: \[([\s\S]*?)\n  \] \}/g;
let m;
while ((m = pageRe.exec(pagesSrc))) {
  const fields = [];
  // A list field carries `item`, a JSON object with no nested braces: the
  // fields, which are required, and how many there may be.
  const fRe = /\{ k: "([^"]+)", label: "([^"]*)", kind: "([^"]+)"(?:, item: (\{[^{}]*\}))? \}/g;
  let f;
  while ((f = fRe.exec(m[4])))
    fields.push({ k: f[1], label: f[2], kind: f[3], item: f[4] ? JSON.parse(f[4]) : null });
  PAGES.push({ key: m[1], title: m[2], path: m[3], fields });
}
ok(PAGES.length > 0, 'and it parses');

// --- the seed's idea -------------------------------------------------------
// Every migration, not only 0035: a later one may add a block, and this has to
// go on being true when it does.
const seeded = new Set();
for (const f of fs.readdirSync(MIG).filter(n => n.endsWith('.sql'))) {
  const sql = fs.readFileSync(path.join(MIG, f), 'utf8');
  if (!/insert into public\.page_blocks/.test(sql)) continue;
  const re = /^\s*\('([a-z0-9-]+)', '([a-z0-9_]+)',/gm;
  let r;
  while ((r = re.exec(sql))) seeded.add(r[1] + '.' + r[2]);
}

// --- the comparisons -------------------------------------------------------
const sitePages  = new Set(Object.keys(BLOCK_MAP));
const adminPages = new Set(PAGES.map(p => p.key));

ok(sitePages.size === adminPages.size
   && [...sitePages].every(k => adminPages.has(k)),
   `the same pages on both sides.\n    site:  ${list(sitePages)}\n    admin: ${list(adminPages)}`);

for (const p of PAGES) {
  const siteKeys  = new Set(Object.keys(BLOCK_MAP[p.key] || {}));
  const adminKeys = new Set(p.fields.map(f => f.k));

  const onlyAdmin = [...adminKeys].filter(k => !siteKeys.has(k));
  const onlySite  = [...siteKeys].filter(k => !adminKeys.has(k));

  ok(onlyAdmin.length === 0,
     `${p.key}: the admin app offers fields the site does not render, so editing them `
     + `would do nothing: ${onlyAdmin.join(', ')}`);
  ok(onlySite.length === 0,
     `${p.key}: the site reads blocks the admin app does not offer, so they cannot be `
     + `edited: ${onlySite.join(', ')}`);

  // The kind has to agree too. A field offered as a line and rendered as prose
  // writes plain text into a run of paragraphs, which does not fail, it just
  // takes the other paragraphs away.
  for (const f of p.fields) {
    const siteKind = (BLOCK_MAP[p.key] || {})[f.k];
    if (!siteKind) continue;
    ok(siteKind[1] === f.kind,
       `${p.key}.${f.k}: the site renders it as ${siteKind[1]} and the admin app offers `
       + `it as ${f.kind}`);
  }

  // Every field is seeded, because a page that is half seeded reads oddly
  // rather than looking broken, which is worse.
  const missing = [...adminKeys].filter(k => !seeded.has(p.key + '.' + k));
  ok(missing.length === 0,
     `${p.key}: fields with no seeded row, so the Pages screen opens them empty: `
     + missing.join(', '));

  // Labels, because the whole argument for this screen over the grid is that a
  // field is named rather than keyed.
  const unlabelled = p.fields.filter(f => !f.label || f.label === f.k);
  ok(unlabelled.length === 0,
     `${p.key}: fields whose label is just the key: ${unlabelled.map(f => f.k).join(', ')}`);
}

// --- the repeating blocks, piece two ---------------------------------------
// The seeded items, read whole. The editor's idea of a list (its fields, its
// count) has to fit what is actually in the database, or the first time
// somebody opens a list it refuses to save the words that are already live.
const seededItems = {};
for (const f of fs.readdirSync(MIG).filter(n => n.endsWith('.sql'))) {
  const sql = fs.readFileSync(path.join(MIG, f), 'utf8');
  const re = /\('([a-z0-9-]+)', '([a-z0-9_]+)', null, '((?:[^']|'')*)'::jsonb/g;
  let r;
  while ((r = re.exec(sql))) seededItems[r[1] + '.' + r[2]] = JSON.parse(r[3].replace(/''/g, "'"));
}

// The icons on both sides are one set of drawings, character for character.
const iconsOf = (src, name) => {
  const a = src.indexOf(name) + name.length;
  return JSON.parse(src.slice(a, src.indexOf('\n};', a) + 2));
};
const SITE_ICONS  = iconsOf(blocksSrc, 'const BLOCK_ICONS = ');
const ADMIN_ICONS = iconsOf(adminSrc, 'const ICONS = ');
ok(Object.keys(SITE_ICONS).length === 15, `fifteen icons on the site, got ${Object.keys(SITE_ICONS).length}`);
ok(JSON.stringify(SITE_ICONS) === JSON.stringify(ADMIN_ICONS),
   'the icon picker offers exactly the drawings the site draws');
ok(Object.values(SITE_ICONS).every(v => /^<svg[^>]*>[\s\S]*<\/svg>$/.test(v) && !/<script|on\w+=/i.test(v)),
   'every icon is a single drawing and nothing else');

// The reader types the site knows how to fill.
const siteJs = fs.readFileSync(path.join(SITE, 'assets/site.js'), 'utf8');
const needsSrc = siteJs.slice(siteJs.indexOf('const LIST_NEEDS = {'));
const siteTypes = new Set([...needsSrc.slice(0, needsSrc.indexOf('};')).matchAll(/^\s+(\w+):/gm)].map(x => x[1]));

for (const p of PAGES) for (const f of p.fields.filter(x => x.kind === 'list')) {
  const where = `${p.key}.${f.k}`;
  const site = (BLOCK_MAP[p.key] || {})[f.k] || [];
  ok(!!f.item, `${where}: the admin app knows what an item of this list is made of`);
  if (!f.item) continue;
  ok(site[2] === f.item.type,
     `${where}: the site fills it as ${site[2]} and the admin app edits it as ${f.item.type}`);
  ok(siteTypes.has(f.item.type), `${where}: site.js knows how to fill a ${f.item.type}`);

  const items = seededItems[where] || [];
  const { min, max, step } = f.item;
  ok(items.length >= min && items.length <= max && items.length % step === 0,
     `${where}: the seeded ${items.length} items fit the rule ${min} to ${max} in steps of ${step}`);
  ok(min <= max && min % step === 0 && max % step === 0,
     `${where}: the rule can be met at all`);
  const allowed = new Set(f.item.fields);
  ok(items.every(it => Object.keys(it).every(k => allowed.has(k))),
     `${where}: every seeded field is one the editor offers, so none is dropped on the first save`);
  ok(items.every(it => f.item.required.every(k => it[k] !== undefined && it[k] !== '' )),
     `${where}: every seeded item has the fields the editor requires`);
  ok(items.every(it => !it.icon || SITE_ICONS[it.icon]),
     `${where}: every seeded icon is one the site can draw`);
  ok(allowed.has('icon') === items.some(it => 'icon' in it),
     `${where}: the editor offers an icon exactly when the cards carry one`);
}

// --- the photographs ---------------------------------------------------------
// One pattern in three places: site.js, the admin app and 0037. The site writes
// the address into a CSS url(), so a looser pattern anywhere is a way in.
const patOf = (src, name) => { const m = src.match(new RegExp('const ' + name + ' = (/.*/);')); return m && m[1]; };
const sitePat  = patOf(siteJs, 'PHOTO_ADDRESS');
const adminPat = patOf(adminSrc, 'PHOTO_ADDRESS');
ok(!!sitePat && sitePat === adminPat, `the site and the admin app check a photograph address the same way\n    site:  ${sitePat}\n    admin: ${adminPat}`);
const mig37 = fs.readFileSync(path.join(MIG, '0037_page_photographs.sql'), 'utf8');
ok(sitePat && mig37.includes(sitePat.slice(1, -1).replace(/\\\//g, '/')),
   'and the database constraint in 0037 uses that pattern too');
const PHOTO_RE = sitePat ? new RegExp(sitePat.slice(1, -1)) : /^$/;
const seededPhotos = [...mig37.matchAll(/\('([a-z0-9-]+)', '([a-z0-9_]+_photo)', '([^']*)'/g)];
ok(seededPhotos.length === 13, `thirteen photographs seeded, got ${seededPhotos.length}`);
for (const [, pk, bk, addr] of seededPhotos) {
  ok(PHOTO_RE.test(addr), `${pk}.${bk}: the seeded address ${addr} passes the pattern`);
  ok(fs.existsSync(path.join(SITE, addr)), `${pk}.${bk}: ${addr} is in the bundle`);
  ok(((BLOCK_MAP[pk] || {})[bk] || [])[1] === 'image', `${pk}.${bk}: the site draws it as a photograph`);
}
const stockSrc = adminSrc.match(/const STOCK_PHOTOS = (\[.*\]);/);
const STOCK = stockSrc ? JSON.parse(stockSrc[1]) : [];
ok(STOCK.length === 5 && STOCK.every(a => fs.existsSync(path.join(SITE, a))),
   'the five photographs the picker offers are all in the bundle');

// --- one global scope ---------------------------------------------------------
// Every public page loads site.js, blocks.js and its own page script into ONE
// global scope. A second top level declaration of a name replaces the first
// with no error (a function) or kills the whole file (a const), and node
// --check sees neither, because each file is fine on its own. It has happened
// twice: const qs in August, and a second photoUrl on 30 October that would
// have taken every member's photograph off the members area.
const topNames = src => [...src.matchAll(/^(?:async\s+)?(?:function\s*\*?\s*|const\s+|let\s+|var\s+|class\s+)([A-Za-z_$][\w$]*)/gm)].map(m => m[1]);
const shared = [...topNames(siteJs), ...topNames(blocksSrc)];
const dupShared = shared.filter((n, i) => shared.indexOf(n) !== i);
ok(dupShared.length === 0, `site.js and blocks.js declare nothing twice: ${dupShared.join(', ')}`);
for (const f of fs.readdirSync(path.join(SITE, 'assets')).filter(n => /^page-.*\.js$/.test(n))) {
  const own = topNames(fs.readFileSync(path.join(SITE, 'assets', f), 'utf8'));
  const clash = own.filter(n => shared.includes(n));
  ok(clash.length === 0, `${f} redeclares nothing from site.js or blocks.js: ${clash.join(', ')}`);
}

// --- no inline handlers -------------------------------------------------------
// The site's policy is script-src 'self' with no 'unsafe-inline', which refuses
// onclick="" and onerror="" as well as <script>. One written into markup is
// therefore dead code that looks like a working fallback. The card page had two
// until 30 October. They are attached from script instead.
for (const f of [...fs.readdirSync(SITE).filter(n => n.endsWith('.html')).map(n => path.join(SITE, n)),
                 ...fs.readdirSync(path.join(SITE, 'assets')).filter(n => n.endsWith('.js'))
                    .map(n => path.join(SITE, 'assets', n))]) {
  if (/supabase\.js$|qrcode\.js$/.test(f)) continue;     // vendored, never in markup
  const src = fs.readFileSync(f, 'utf8');
  const hit = src.match(/<[a-z][^>]*\son[a-z]+\s*=\s*["']/i);
  ok(!hit, `${path.basename(f)} writes no inline event handler, which the policy would refuse: ${hit ? hit[0].slice(0, 60) : ''}`);
}

// Nothing is seeded that neither side knows about. A stray row is harmless on
// the site and is a block somebody will eventually find and wonder about.
const known = new Set();
Object.entries(BLOCK_MAP).forEach(([pk, keys]) =>
  Object.keys(keys).forEach(k => known.add(pk + '.' + k)));
const stray = [...seeded].filter(k => !known.has(k));
ok(stray.length === 0, `seeded blocks nothing reads: ${stray.join(', ')}`);

// And the privacy notice stays out of all three, which is a decision rather
// than an oversight and is the sort of decision somebody tidies up.
ok(!sitePages.has('privacy') && !adminPages.has('privacy')
   && ![...seeded].some(k => k.startsWith('privacy.')),
   'the privacy notice is in none of the three, which is deliberate: see 0035');

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
